param([Parameter(Mandatory)][string]$InputPath,[Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop'
$r=Get-Content -LiteralPath $InputPath -Raw|ConvertFrom-Json
$rows=foreach($s in $r.states){[pscustomobject]@{state=$s.name;mode=$s.mode;appearance=$s.appearance;motion=$s.motion;frameMs=$s.frameMilliseconds;gpuMs=$s.gpuMilliseconds;mainElapsedMs=$s.profiler[0].milliseconds;grassCameraMs=$s.profiler[7].milliseconds;drawCalls=$s.profiler[3];setPass=$s.profiler[4];triangles=$s.profiler[5];vertices=$s.profiler[6];conditions=($s.sameWithinState -and $s.sameAsS0);samples=$s.raw.Count;layers=$s.layers|Select-Object name,clumps,ownedRenderers,ownedMaterials,dataDensity,placementsFingerprint;camera=$s.before|Select-Object screenWidth,screenHeight,cameraPosition,cameraRotation,quality,vSync,targetFrameRate;environmentSeconds=@($s.environmentSecondsStart,$s.environmentSecondsEnd)}}
$valid=$r.completed -and $r.comparable -and !$r.error -and $r.states.Count -eq 4 -and $r.cleanupWarnings.Count -eq 0 -and @($rows|Where-Object { !$_.conditions -or $_.drawCalls.p50 -le 0 -or $_.camera.screenWidth -ne 1600 -or $_.camera.screenHeight -ne 900 }).Count -eq 0
$summary=[pscustomobject]@{validRenderedFourState=$valid;sourcePath=[IO.Path]::GetFullPath($InputPath);sourceSha=(Get-FileHash -LiteralPath $InputPath).Hash;startedUtc=$r.startedUtc;finishedUtc=$r.finishedUtc;device=$r.graphicsDevice;processor=$r.processor;api=$r.graphicsApi;editor=$r.editor;completed=$r.completed;comparable=$r.comparable;error=$r.error;cleanupWarnings=$r.cleanupWarnings;states=$rows;deltaP50ms=[pscustomobject]@{staticMinusGround=$rows[1].frameMs.p50-$rows[0].frameMs.p50;windMinusStatic=$rows[2].frameMs.p50-$rows[1].frameMs.p50;completeMinusGround=$rows[3].frameMs.p50-$rows[0].frameMs.p50};limits='Frame/Main elapsed includes waits. GPU unavailable remains null; GPU budget not certified. Independent Lab is not Main 60FPS evidence. Hidden zero-draw run invalidated separately.'}
$summary|ConvertTo-Json -Depth 12|Set-Content -LiteralPath $OutputPath -Encoding utf8
$summary|Select-Object validRenderedFourState,deltaP50ms,device|ConvertTo-Json -Depth 4
